import codecs
failure = ValueError('mapping service')
events = []
class Mapping:
    def __getitem__(self, point):
        events.append(point)
        if point == 90 or point == 63:
            return point
        return None
class Position:
    def __index__(self):
        answer = input()
        if answer == 'failure':
            raise failure
        assert answer == 'resume'
        return -1
def recover(error):
    print(error.encoding, error.start, error.end, error.reason)
    return ('?', Position())
codecs.register_error('charmap_service', recover)
try:
    result = codecs.charmap_encode('\ud800Z', 'charmap_service', Mapping())
except ValueError as error:
    assert error is failure
    print('failure retained', error.args)
else:
    print(result)
print(events)

